);

const NetworkBackground = () => {
  const particlesInit = useCallback(async (engine) => {
    await loadFull(engine);
  }, []);

  const options = {
    fullScreen: { enable: true, zIndex: -1 },
    background: { color: { value: "#ffffff" } },
    fpsLimit: 60,
    interactivity: {
      detectsOn: "canvas",
      events: { onHover: { enable: true, mode: "repulse" }, resize: true },
      modes: { repulse: { distance: 100, duration: 0.4 } },
    },
    particles: {
      color: { value: "#34d399" },
      links: { color: "#34d399", distance: 150, enable: true, opacity: 0.2, width: 1 },
      collisions: { enable: false },
      move: {
        direction: "none",
        enable: true,
        outModes: { default: "bounce" },
        random: true,
        speed: 1.5,
        straight: false,
      },
      number: { density: { enable: true, area: 800 }, value: 50 },
      opacity: { value: 0.3 },
      shape: { type: "circle" },
      size: { value: { min: 1, max: 3 } },
    },
    detectRetina: true,
  };

  return <Particles id="tsparticles" init={particlesInit} options={options} />;
};


// --- Main Page Component ---
export default function MentorPage() {
  const [search, setSearch] = useState("");
  const [activeExpertise, setActiveExpertise] = useState("Software Engineering");

  const filteredProfiles = mentorProfiles.filter((m) => {
    const text = (m.name + " " + m.role).toLowerCase();
    const q = search.toLowerCase();
    const matchesSearch = !q || text.includes(q);
    const matchesExpertise = activeExpertise ? m.role === activeExpertise : true;
    return matchesSearch && matchesExpertise;
  });

  return (
    <div className="relative min-h-screen bg-white">
      <NetworkBackground />
      <Navbar />

      <main className="relative z-10 max-w-6xl mx-auto px-4 pt-12 pb-24 xl:px-0">
        
        {/* Mentors Section */}
        <section className="mb-16">
          <div className="bg-white/95 rounded-2xl shadow-lg border border-gray-100 px-6 sm:px-8 pt-8 pb-10">
            {/* Search Bar */}
            <div className="relative w-full mb-6">
                <MagnifyingGlassIcon className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                <input
                    type="text"
                    placeholder="Search mentors by name or expertise"
                    className="w-full rounded-lg border border-gray-200 bg-gray-50 pl-11 pr-4 py-2.5 text-sm outline-none focus:ring-2 focus:ring-emerald-300"
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                />
            </div>

            {/* Expertise Tabs */}
            <div className="flex space-x-2 mb-8 overflow-x-auto pb-2">
              {expertiseTabs.map((tab) => (
                <button
                  key={tab}
                  onClick={() => setActiveExpertise(tab)}
                  className={`flex-shrink-0 px-4 py-1.5 rounded-lg text-xs font-semibold border ${
                    activeExpertise === tab
                      ? "bg-emerald-500 text-white border-emerald-500"
                      : "bg-white text-gray-600 border-gray-200 hover:bg-gray-100"
                  }`}
                >
                  {tab}
                </button>
              ))}
            </div>

            {/* Mentor Avatars */}
            <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-x-6 gap-y-8 mb-8">
              {filteredProfiles.map((m) => (
                <div key={m.name} className="flex flex-col items-center text-center">
                  <div className="w-24 h-24 rounded-full overflow-hidden mb-2 border-2 border-white shadow-lg">
                    <img src={m.image} alt={m.name} className="w-full h-full object-cover" />
                  </div>
                  <div className="text-sm font-semibold text-gray-800">{m.name}</div>
                  <div className="text-xs text-gray-500">{m.role}</div>
                </div>
              ))}
            </div>

            {/* Buttons */}
            <div className="flex flex-col sm:flex-row justify-center items-center gap-4 mt-4">
              <button className="px-6 py-2 rounded-lg bg-emerald-500 text-white text-sm font-semibold hover:bg-emerald-600 shadow-sm">
                Request Mentorship
              </button>
              <button className="px-6 py-2 rounded-lg bg-gray-100 text-gray-800 text-sm font-semibold border border-gray-200 hover:bg-gray-200">
                View Profile
              </button>
            </div>
          </div>
        </section>

        {/* For Mentorship Section */}
        <section>
          <div className="bg-white/95 rounded-2xl shadow-lg border border-gray-100 px-6 sm:px-10 py-10 flex flex-col md:flex-row gap-8 items-center">
            <div className="md:w-1/2 flex justify-center">
              <div className="rounded-2xl overflow-hidden bg-gray-100 max-w-sm w-full shadow-md">
                <img src="https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=500&q=80" alt="A smiling mentor at a desk" className="w-full h-full object-cover" />
              </div>
            </div>
            <div className="md:w-1/2 w-full">
              <h2 className="text-2xl font-bold mb-2 text-gray-800">For Mentorship</h2>
              <p className="text-sm text-gray-600 mb-6">
                Got questions about the Landing Page UI Kit? Our team is here to help. Contact us for quick and friendly support.
              </p>
              <div className="space-y-4">
                <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">👤</span>
                  <input type="text" placeholder="Full Name" className="w-full h-12 rounded-lg border border-gray-200 pl-11 pr-4 text-sm outline-none focus:ring-2 focus:ring-emerald-300" />
                </div>
                <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">✉️</span>
                  <input type="email" placeholder="Email" className="w-full h-12 rounded-lg border border-gray-200 pl-11 pr-4 text-sm outline-none focus:ring-2 focus:ring-emerald-300" />
                </div>
                <button className="w-full mt-2 px-6 py-3 rounded-lg bg-emerald-500 text-white font-semibold hover:bg-emerald-600 shadow-md">
